// Host build: which overlays are loaded, and calls to addresses that several overlays share (docs/host.md).
//
// The original's main code holds fixed addresses inside overlays (action tables, callbacks); the same address is a
// different function depending on the overlay loaded there. The host has every overlay linked in, so each such
// reference goes to a dispatcher (Shared_<name>, generated by tools/host_shared_calls.py) that asks
// Modern_SharedResolve for the candidate whose overlay is loaded.

#include "types.h"
#include "host_shared_calls.h"

#define MODERN_MAX_OVERLAYS 160

static u8 sOverlayLoaded[MODERN_MAX_OVERLAYS];
static u32 sOverlayStart[MODERN_MAX_OVERLAYS];
static u32 sOverlayEnd[MODERN_MAX_OVERLAYS];

// FS_StartOverlay: an overlay was loaded over [start, end); the overlays it overlaps are gone
void Modern_OverlayStarted(u32 id, u32 start, u32 end) {
    u32 i;
    for (i = 0; i < MODERN_MAX_OVERLAYS; i++) {
        if (sOverlayLoaded[i] && sOverlayStart[i] < end && start < sOverlayEnd[i]) {
            sOverlayLoaded[i] = 0;
        }
    }
    if (id < MODERN_MAX_OVERLAYS) {
        sOverlayLoaded[id] = 1;
        sOverlayStart[id] = start;
        sOverlayEnd[id] = end;
    }
}

// FS_EndOverlay
void Modern_OverlayEnded(u32 id) {
    if (id < MODERN_MAX_OVERLAYS) {
        sOverlayLoaded[id] = 0;
    }
}

BOOL Modern_IsOverlayLoaded(u32 id) {
    return id < MODERN_MAX_OVERLAYS && sOverlayLoaded[id];
}

// The candidates of a call to an address several overlays share (include/host_shared_calls.h, generated by
// tools/host_shared_calls.py): the first whose overlay is loaded, the named one (the first) when none is.
void *Modern_SharedResolve(const HostSharedCall *call) {
    u32 i;
    for (i = 0; i < call->count; i++) {
        if (Modern_IsOverlayLoaded(call->cands[i].overlay)) {
            return (void *)call->cands[i].addr;
        }
    }
    return (void *)call->cands[0].addr;
}
